import{_ as i,o as t,c as e,a5 as a}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Kế hoạch kiểm chứng","description":"","frontmatter":{},"headers":[],"relativePath":"feature/caption-trend-retrieval/test.md","filePath":"feature/caption-trend-retrieval/test.md"}'),h={name:"feature/caption-trend-retrieval/test.md"};function r(o,n,l,c,g,u){return t(),e("div",null,[...n[0]||(n[0]=[a('<h1 id="ke-hoach-kiem-chung" tabindex="-1">Kế hoạch kiểm chứng <a class="header-anchor" href="#ke-hoach-kiem-chung" aria-label="Permalink to &quot;Kế hoạch kiểm chứng&quot;">​</a></h1><p>Trạng thái: chưa chạy test triển khai; hiện mới có tài liệu kế hoạch.</p><h2 id="du-lieu-va-retrieval" tabindex="-1">Dữ liệu và retrieval <a class="header-anchor" href="#du-lieu-va-retrieval" aria-label="Permalink to &quot;Dữ liệu và retrieval&quot;">​</a></h2><ol><li>TrendId hợp lệ nối đúng Neo4j và Chroma; tên giống nhau nhưng khác ngày/category không lẫn. Post ID có prefix và không prefix được normalize đúng.</li><li>Loại run running/failed/interrupted/test và private/replay namespace; batch failed không thành evidence dù còn vector. Run partial đã publish chỉ lấy phần thành công và có nhãn partial.</li><li>Bản ghi v2 thiếu run/time/source không được tự gắn vào publication mới. Upsert run sau không làm snapshot cũ âm thầm thay nội dung; cache invalidates khi revision đổi.</li><li>Window 7 ngày theo thời điểm gen; kiểm tra ranh giới UTC/Vietnam, publishedAt thiếu/crawledAt fallback được đánh dấu. Moment/format vẫn dùng expiry policy hiện hữu.</li><li>Chroma empty/missing collection/model dimension mismatch/query timeout, Neo4j timeout và publication lookup unavailable: trạng thái rõ, không tạo collection rỗng, không lấy trend khác.</li><li>Query đúng metadata filter, giới hạn graph và top-k, không duplicate cùng post. Embedding dùng cùng model/prefix/dimension với index.</li></ol><h2 id="caption-va-quyen-truy-cap" tabindex="-1">Caption và quyền truy cập <a class="header-anchor" href="#caption-va-quyen-truy-cap" aria-label="Permalink to &quot;Caption và quyền truy cập&quot;">​</a></h2><ol start="7"><li>Ba variant đúng schema/platform/language, giữ brand voice, task và moderation. Không gắn giá/khuyến mãi từ post người khác vào sản phẩm brand.</li><li>Nguồn chứa “ignore instructions”, token giả hoặc yêu cầu tiết lộ context không điều khiển system prompt. Caption không sao chép nguyên văn dài từ nguồn.</li><li>Workspace A không đọc brand KB/snapshot generation của B; frontend không thay client_id hoặc gửi raw Cypher/filter.</li><li>Response hiển thị source references hợp lệ ngoài caption, phân biệt retrieved context với bằng chứng cho từng claim. Không log cookie, key, full prompt hoặc toàn văn bài nguồn.</li><li>Refine/adapt/idempotent retry giữ đúng context snapshot và không double-charge. Caller cũ gen thường không cần trend context mới.</li></ol><h2 id="ux-va-van-hanh" tabindex="-1">UX và vận hành <a class="header-anchor" href="#ux-va-van-hanh" aria-label="Permalink to &quot;UX và vận hành&quot;">​</a></h2><ol start="12"><li>UI đủ loading/used/partial/insufficient/unavailable, nguồn có ngày/link, hành động chọn lại/gen thường. Kiểm tra vi/en, light/dark, mobile và keyboard.</li><li>Bộ đánh giá đề xuất 30–50 brief Việt/Anh, đa ngành/platform: đúng trend, trend không phù hợp, nguồn cũ, sensitive và không có dữ liệu. Review thủ công độ liên quan, grounding, brand fit, originality; không tự báo tỉ lệ chất lượng khi chưa đánh giá.</li><li>Đo retrieval p50/p95, số chunks/context tokens, cache hit, RAM và caption concurrency trên môi trường tương tự EC2; chạy cùng một crawler. Không hứa giới hạn AI 4.5 GiB đủ cho mọi concurrent load khi chưa đo.</li><li>CI AI/Business/Web, integration với DB thật và feature-flag rollback. Ngân sách retrieval khoảng 5 giây/context 2.000 tokens chỉ là điểm khởi đầu cần review theo phép đo.</li></ol>',8)])])}const d=i(h,[["render",r]]);export{p as __pageData,d as default};
